const tests = [
  "https://www.plantuml.com/plantuml/png/",
  "https://kroki.io/plantuml/png",
];
const results = [];
for (const url of tests) {
  try {
    const r = await fetch(url, { method: "POST", headers: { "Content-Type": "text/plain" }, body: "@startuml\nA -> B\n@enduml", signal: AbortSignal.timeout(15000) });
    const buf = Buffer.from(await r.arrayBuffer());
    results.push({ url, status: r.status, contentType: r.headers.get("content-type"), bytes: buf.length, head: buf.slice(0, 8).toString("hex") });
  } catch (e) {
    results.push({ url, error: String(e && e.message || e) });
  }
}
return results;

